"""Tiny generated bytes and syscall doubles only; never a real release or ML import."""

from __future__ import annotations

import hashlib
import importlib
import json
import os
import sys
import tempfile
import types
import unittest
from pathlib import Path
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
PACKAGE = "_lumi_synthetic_release_verifier_v1"
package = types.ModuleType(PACKAGE)
package.__path__ = [str(ROOT / "src/lumi")]
sys.modules[PACKAGE] = package
before_import = set(sys.modules)
verifier = importlib.import_module(PACKAGE + ".posttraining_sft_release_verifier_v1")
IMPORT_ADDITIONS = set(sys.modules) - before_import
LIMITS = {
    "maximum_manifest_bytes": 32768, "maximum_entries": 16,
    "maximum_file_bytes": 4096, "maximum_total_bytes": 16384,
    "maximum_tree_entries": 64, "maximum_content_read_bytes": 32768,
    "maximum_opens": 128, "maximum_runtime_ms": 1000,
}
PAYLOADS = {
    "dependencies/pkg/module.py": b"SYNTHETIC-DEPENDENCY",
    "runtime/bin/python3.12": b"\x7fELFSYNTHETIC-NEVER-EXECUTE",
    "source/worker.py": b"SYNTHETIC-SOURCE-NEVER-IMPORT",
}


def encoded(value):
    return json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":")).encode()


class GeneratedTreeTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix="lumi-release-synthetic-")
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name).resolve() / "release"
        self.root.mkdir(mode=0o700)
        self.value = {
            "schema": verifier.manifest.SCHEMA, "platform": "linux-x86_64",
            "python_abi": "cp312", "interpreter": "runtime/bin/python3.12",
            "entrypoint": "source/worker.py", "files": [],
        }
        for name, content in sorted(PAYLOADS.items()):
            target = self.root / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content)
            mode = 0o755 if name.startswith("runtime/") else 0o644
            target.chmod(mode)
            role = {"dependencies": "dependency", "runtime": "runtime", "source": "source"}[
                name.split("/")[0]]
            self.value["files"].append({
                "path": name, "sha256": hashlib.sha256(content).hexdigest(),
                "bytes": len(content), "mode": mode, "role": role,
            })
        for directory in (self.root / "dependencies", self.root / "dependencies/pkg",
                          self.root / "runtime", self.root / "runtime/bin", self.root / "source"):
            directory.chmod(0o755)
        # Only this tiny generated-tree API is exercised on macOS. No Linux
        # fixture/wrapper, release executable, ML package or model is imported.
        self.runtime_patch = patch.object(verifier, "_runtime", return_value=None)
        self.runtime_patch.start()
        self.addCleanup(self.runtime_patch.stop)

    def verify(self, **overrides):
        raw = encoded(self.value)
        arguments = {
            "root": str(self.root), "raw_manifest": raw,
            "expected_sha256": hashlib.sha256(raw).hexdigest(), "limits": dict(LIMITS),
            "expected_uid": os.getuid(), "expected_gid": os.getgid(),
        }
        arguments.update(overrides)
        return verifier.verify_release(**arguments)

    def reject(self, code, **overrides):
        with self.assertRaises(verifier.ReleaseVerificationError) as caught:
            self.verify(**overrides)
        self.assertEqual(caught.exception.code, code)
        self.assertEqual(caught.exception.args, (code,))
        self.assertEqual(str(caught.exception), code)
        self.assertNotIn(str(self.root), repr(caught.exception))
        self.assertIsNone(caught.exception.__cause__)
        return caught.exception

    def test_exact_generated_tree_has_only_aggregate_claims(self):
        result = self.verify()
        self.assertEqual(result["status"], "verified")
        self.assertEqual(result["files_verified"], 3)
        self.assertEqual(result["directories_verified"], 6)
        self.assertEqual(result["tree_entries_examined"], 8)
        size = sum(map(len, PAYLOADS.values()))
        self.assertEqual(result["content_read_bytes"], size)
        self.assertEqual(result["reserved_read_bytes"], size + 3)
        self.assertEqual(result["handles_opened"], result["handles_closed"])
        self.assertEqual(result["open_attempts"], result["handles_opened"])
        self.assertTrue(result["exact_tree_matched"])
        self.assertTrue(result["root_identity_stable"])
        for key in verifier.NONCLAIMS:
            self.assertIs(result[key], False)
        text = json.dumps(result)
        self.assertNotIn(str(self.root), text)
        for content in PAYLOADS.values():
            self.assertNotIn(content.decode(), text)
        self.assertEqual(set(result), {
            "schema", "status", "manifest_sha256", "files_verified", "directories_verified",
            "content_read_bytes", "reserved_read_bytes", "tree_entries_examined", "open_attempts",
            "handles_opened", "handles_closed", "exact_tree_matched", "root_identity_stable",
            *verifier.NONCLAIMS,
        })

    def test_no_release_code_is_executed_or_imported(self):
        with patch("builtins.__import__", side_effect=AssertionError("unexpected import")):
            self.assertEqual(self.verify()["files_verified"], 3)

    def test_external_pin_rejected_before_any_open(self):
        with patch.object(verifier.os, "open", side_effect=AssertionError) as opened:
            self.reject("manifest_hash_mismatch", expected_sha256="0" * 64)
        opened.assert_not_called()

    def test_invalid_configuration_rejected_before_any_open(self):
        with patch.object(verifier.os, "open", side_effect=AssertionError) as opened:
            for key in LIMITS:
                for invalid in (True, 0, -1, 1.0, "4", None, 10**40):
                    with self.subTest(key=key, invalid=invalid):
                        self.reject("configuration_rejected", limits=LIMITS | {key: invalid})
            self.reject("configuration_rejected", limits=LIMITS | {"unknown": 1})
            self.reject("configuration_rejected", limits={})
            self.reject("configuration_rejected", limits=None)
            self.reject("configuration_rejected", expected_uid=True)
            self.reject("configuration_rejected", expected_gid=-1)
        opened.assert_not_called()

    def test_root_aliases_rejected_without_open(self):
        with patch.object(verifier.os, "open", side_effect=AssertionError) as opened:
            for root in ("/", "//private", "relative", "/private//test", "/private/./test",
                         "/private/../test", "/private/test/", "/private/test\x00",
                         "/private/test\n", "/private/te\\st", None, b"/private/test"):
                with self.subTest(root=root):
                    self.reject("root_rejected", root=root)
        opened.assert_not_called()

    def test_tree_budget_rejects_before_open(self):
        with patch.object(verifier.os, "open", side_effect=AssertionError) as opened:
            self.reject("entry_budget_exhausted", limits=LIMITS | {"maximum_tree_entries": 7})
        opened.assert_not_called()

    def test_read_budget_includes_one_eof_probe_per_file(self):
        minimum = sum(map(len, PAYLOADS.values())) + 3
        with patch.object(verifier.os, "open", side_effect=AssertionError) as opened:
            self.reject("read_budget_exhausted", limits=LIMITS | {
                "maximum_content_read_bytes": minimum - 1})
        opened.assert_not_called()
        self.assertEqual(self.verify(limits=LIMITS | {
            "maximum_content_read_bytes": minimum})["reserved_read_bytes"], minimum)

    def test_open_budget_is_prepaid(self):
        real_open = os.open
        with patch.object(verifier.os, "open", wraps=real_open) as opened:
            self.reject("open_budget_exhausted", limits=LIMITS | {"maximum_opens": 1})
        self.assertEqual(opened.call_count, 1)

    def test_missing_file_rejected(self):
        (self.root / "source/worker.py").unlink()
        self.reject("tree_rejected")

    def test_extra_file_rejected(self):
        (self.root / "source/unlisted.py").write_bytes(b"UNLISTED-SYNTHETIC")
        self.reject("tree_rejected")

    def test_empty_extra_directory_rejected(self):
        (self.root / "source/unlisted").mkdir()
        self.reject("tree_rejected")

    def test_same_size_content_tamper_rejected(self):
        name = "dependencies/pkg/module.py"
        (self.root / name).write_bytes(b"x" * len(PAYLOADS[name]))
        self.reject("digest_mismatch")

    def test_wrong_size_rejected(self):
        (self.root / "source/worker.py").write_bytes(b"x")
        self.reject("file_rejected")

    def test_file_mode_mismatch_rejected(self):
        (self.root / "source/worker.py").chmod(0o600)
        self.reject("mode_rejected")

    def test_world_writable_directory_rejected(self):
        (self.root / "source").chmod(0o777)
        self.reject("mode_rejected")

    def test_world_writable_root_rejected(self):
        self.root.chmod(0o777)
        self.reject("mode_rejected")

    def test_wrong_owner_rejected(self):
        self.reject("owner_rejected", expected_uid=os.getuid() + 1)

    def test_wrong_group_rejected(self):
        self.reject("owner_rejected", expected_gid=os.getgid() + 1)

    def test_interpreter_must_have_elf_prefix(self):
        name = "runtime/bin/python3.12"
        raw = b"XXXX" + PAYLOADS[name][4:]
        (self.root / name).write_bytes(raw)
        self.value["files"][1]["sha256"] = hashlib.sha256(raw).hexdigest()
        self.reject("interpreter_rejected")

    def test_empty_interpreter_rejected(self):
        (self.root / "runtime/bin/python3.12").write_bytes(b"")
        self.value["files"][1].update(bytes=0, sha256=hashlib.sha256(b"").hexdigest())
        self.reject("interpreter_rejected")

    def test_empty_noninterpreter_file_allowed(self):
        (self.root / "dependencies/pkg/module.py").write_bytes(b"")
        self.value["files"][0].update(bytes=0, sha256=hashlib.sha256(b"").hexdigest())
        self.assertEqual(self.verify()["files_verified"], 3)

    def test_symlink_file_rejected_without_target_read(self):
        target = self.root / "source/worker.py"
        target.unlink()
        target.symlink_to(self.root / "dependencies/pkg/module.py")
        self.reject("io_failed")

    def test_symlink_directory_rejected(self):
        original = self.root / "source"
        original.rename(self.root.parent / "moved-source")
        original.symlink_to(self.root.parent / "moved-source", target_is_directory=True)
        self.reject("io_failed")

    def test_symlink_root_rejected(self):
        link = self.root.parent / "root-link"
        link.symlink_to(self.root, target_is_directory=True)
        self.reject("io_failed", root=str(link))

    def test_hardlink_file_rejected(self):
        os.link(self.root / "source/worker.py", self.root.parent / "outside-hardlink")
        self.reject("file_rejected")

    def test_fifo_rejected_without_blocking_read(self):
        target = self.root / "source/worker.py"
        target.unlink()
        os.mkfifo(target, mode=0o644)
        self.reject("file_rejected")

    def test_directory_instead_of_file_rejected(self):
        target = self.root / "source/worker.py"
        target.unlink()
        target.mkdir()
        self.reject("file_rejected")

    def test_changed_file_after_hash_is_rejected(self):
        original = verifier.Reader.file

        def replaced(reader, descriptor, row, *, interpreter):
            result = original(reader, descriptor, row, interpreter=interpreter)
            if row["role"] == "source":
                target = self.root / row["path"]
                target.unlink()
                target.write_bytes(PAYLOADS[row["path"]])
                target.chmod(row["mode"])
            return result

        with patch.object(verifier.Reader, "file", new=replaced):
            self.reject("file_changed")

    def test_root_replacement_after_walk_is_rejected(self):
        original = verifier.Reader.walk

        def replaced(reader, descriptor, prefix, children, rows, interpreter):
            original(reader, descriptor, prefix, children, rows, interpreter)
            if prefix == "":
                self.root.rename(self.root.parent / "old-root")
                self.root.mkdir(mode=0o700)

        with patch.object(verifier.Reader, "walk", new=replaced):
            self.reject("file_changed")

    def test_receipt_does_not_claim_coherent_snapshot_or_immutability(self):
        original = verifier.Reader.file

        def later_change(reader, descriptor, row, *, interpreter):
            result = original(reader, descriptor, row, interpreter=interpreter)
            if row["role"] == "source":
                # The dependency was already observed and closed. An in-place
                # change does not alter its parent directory's identity/mtime.
                target = self.root / "dependencies/pkg/module.py"
                target.write_bytes(b"x" * target.stat().st_size)
            return result

        with patch.object(verifier.Reader, "file", new=later_change):
            result = self.verify()
        self.assertIs(result["point_in_time_snapshot_verified"], False)
        self.assertIs(result["immutable_during_execution"], False)
        self.assertIs(result["execution_permitted"], False)
        self.reject("digest_mismatch")

    def test_runtime_rejection_happens_before_manifest_and_files(self):
        with patch.object(verifier, "_runtime", side_effect=verifier.ReleaseVerificationError(
                "runtime_rejected")), patch.object(verifier.manifest, "validate_manifest") as parse:
            with patch.object(verifier.os, "open") as opened:
                self.reject("runtime_rejected")
        parse.assert_not_called()
        opened.assert_not_called()

    def test_file_disappearing_after_open_closes_all_descriptors(self):
        original_open, original_fstat, descriptors = os.open, os.fstat, []
        selected = None

        def opened(name, *args, **kwargs):
            nonlocal selected
            descriptor = original_open(name, *args, **kwargs)
            descriptors.append(descriptor)
            if name == "module.py":
                selected = descriptor
            return descriptor

        def failed(descriptor):
            if descriptor == selected:
                raise OSError("SYNTHETIC-PRIVATE-FSTAT-FAILURE")
            return original_fstat(descriptor)

        with patch.object(verifier.os, "open", side_effect=opened), patch.object(
                verifier.os, "fstat", side_effect=failed):
            self.reject("io_failed")
        for descriptor in set(descriptors):
            with self.assertRaises(OSError):
                original_fstat(descriptor)

    def test_all_opened_descriptors_close_after_digest_failure(self):
        target = self.root / "dependencies/pkg/module.py"
        target.write_bytes(b"x" * target.stat().st_size)
        original, descriptors = os.open, []

        def opened(*args, **kwargs):
            descriptor = original(*args, **kwargs)
            descriptors.append(descriptor)
            return descriptor

        with patch.object(verifier.os, "open", side_effect=opened):
            self.reject("digest_mismatch")
        self.assertGreater(len(descriptors), 1)
        for descriptor in set(descriptors):
            with self.assertRaises(OSError):
                os.fstat(descriptor)

    def test_ambiguous_close_is_not_retried(self):
        original, closed = os.close, []

        def ambiguous(descriptor):
            closed.append(descriptor)
            original(descriptor)
            if len(closed) == 1:
                raise OSError("SYNTHETIC-PRIVATE-CLOSE-DETAIL")

        with patch.object(verifier.os, "close", side_effect=ambiguous):
            self.reject("cleanup_failed")
        self.assertEqual(len(closed), 2)
        self.assertEqual(len(set(closed)), 2)

    def test_underlying_os_error_text_is_not_retained(self):
        with patch.object(verifier.os, "open", side_effect=OSError("SYNTHETIC-PRIVATE-PATH")):
            caught = self.reject("io_failed")
        self.assertNotIn("SYNTHETIC-PRIVATE", repr(caught))

    def test_interrupt_becomes_fixed_failure_and_closes(self):
        with patch.object(verifier.os, "read", side_effect=KeyboardInterrupt("PRIVATE")):
            self.reject("io_failed")

    def test_deadline_after_manifest_parsing_before_open(self):
        clock = types.SimpleNamespace(monotonic_ns=unittest.mock.Mock(side_effect=[0, 1_000_000]))
        with patch.object(verifier, "time", clock), patch.object(verifier.os, "open") as opened:
            self.reject("deadline_exhausted", limits=LIMITS | {"maximum_runtime_ms": 1})
        opened.assert_not_called()

    def test_read_deadline_checks_after_syscall(self):
        reader = verifier.Reader(dict(LIMITS), os.getuid(), os.getgid())
        with patch.object(reader, "check", side_effect=[None, verifier.ReleaseVerificationError(
                "deadline_exhausted")]), patch.object(verifier.os, "read", return_value=b"x"):
            with self.assertRaisesRegex(verifier.ReleaseVerificationError, "^deadline_exhausted$"):
                reader.read(-1, 4)
        self.assertEqual(reader.reserved, 4)
        self.assertEqual(reader.read_bytes, 1)

    def test_failed_read_still_prepays_capacity(self):
        reader = verifier.Reader(dict(LIMITS), os.getuid(), os.getgid())
        with patch.object(verifier.os, "read", side_effect=OSError("PRIVATE")):
            with self.assertRaises(OSError):
                reader.read(-1, 7)
        self.assertEqual(reader.reserved, 7)
        self.assertEqual(reader.read_bytes, 0)

    def test_short_reads_are_conservatively_budgeted(self):
        original = os.read

        def shortened(descriptor, capacity):
            return original(descriptor, min(capacity, 4))

        size = sum(map(len, PAYLOADS.values())) + 3
        with patch.object(verifier.os, "read", side_effect=shortened):
            self.reject("read_budget_exhausted", limits=LIMITS | {
                "maximum_content_read_bytes": size})


class RuntimeContractTests(unittest.TestCase):
    def runtime(self, **changes):
        expected = {
            "platform": "linux", "implementation": types.SimpleNamespace(name="cpython"),
            "version_info": (3, 12, 1), "flags": types.SimpleNamespace(no_site=1),
            "dont_write_bytecode": True, "modules": {},
        }
        expected.update(changes)
        return types.SimpleNamespace(**expected)

    def test_runtime_guard_accepts_only_supported_pre_ml_context(self):
        main = object()
        threading = types.SimpleNamespace(
            current_thread=lambda: main, main_thread=lambda: main, active_count=lambda: 1)
        with patch.object(verifier, "sys", self.runtime()), patch.object(verifier, "threading",
                threading), patch.object(verifier.platform, "machine", return_value="x86_64"):
            verifier._runtime()

    def test_wrong_runtime_and_ml_imports_reject(self):
        values = [
            {"platform": "darwin"}, {"version_info": (3, 11, 0)},
            {"implementation": types.SimpleNamespace(name="pypy")},
            {"flags": types.SimpleNamespace(no_site=0)}, {"dont_write_bytecode": False},
            *({"modules": {name: object()}} for name in (
                "torch", "numpy.linalg", "transformers", "tensorflow", "jax", "cuda", "cupy")),
        ]
        with patch.object(verifier.platform, "machine", return_value="x86_64"):
            for value in values:
                with self.subTest(value=value), patch.object(
                        verifier, "sys", self.runtime(**value)):
                    with self.assertRaisesRegex(verifier.ReleaseVerificationError,
                                                "^runtime_rejected$"):
                        verifier._runtime()

    def test_wrong_architecture_rejects(self):
        with patch.object(verifier, "sys", self.runtime()), patch.object(verifier.platform,
                "machine", return_value="aarch64"):
            with self.assertRaisesRegex(verifier.ReleaseVerificationError, "^runtime_rejected$"):
                verifier._runtime()

    def test_additional_threads_reject(self):
        with patch.object(verifier, "sys", self.runtime()), patch.object(verifier.platform,
                "machine", return_value="x86_64"), patch.object(verifier.threading,
                "active_count", return_value=2):
            with self.assertRaisesRegex(verifier.ReleaseVerificationError, "^runtime_rejected$"):
                verifier._runtime()

    def test_unknown_error_is_fixed(self):
        self.assertEqual(str(verifier.ReleaseVerificationError("PRIVATE")), "io_failed")
        self.assertEqual(str(verifier.ReleaseVerificationError([])), "io_failed")

    def test_imports_add_no_ml_modules(self):
        self.assertFalse({"torch", "numpy", "transformers", "tensorflow", "jax", "cuda", "cupy"}
                         & {name.split(".", 1)[0] for name in IMPORT_ADDITIONS})


if __name__ == "__main__":
    unittest.main()
